-- Let the requirement migrations bind to a source version on an empty database.
--
-- WHY THIS FILE EXISTS
--
-- `visa_requirements.source_version_id` is NOT NULL by design: a claim about
-- what a government demands must be bound to the exact page version it was read
-- from. The 195 generated requirement migrations resolve that binding with a
-- subquery on the source's currently-active version.
--
-- Nothing in the chain ever created a version row. Versions come from the sync
-- job at runtime, so the chain only ever worked on a database that had already
-- synced. On an empty one, `supabase db reset` failed at
-- 20260821120000_ca_visitor_visa_requirements.sql with a not-null violation on
-- source_version_id, and every requirement migration after it failed the same
-- way. The schema was replayable; the data was not.
--
-- WHAT THESE ROWS ARE
--
-- Real fetch records, exported from production (self-hosted Supabase on the VPS)
-- on 2026-09-04: the 306 currently-active versions, one per source ever fetched
-- successfully. Every hash below is the hash of bytes an authority actually
-- served. Nothing here is synthesized.
--
-- That distinction is the point. The alternative — inventing hashes for pages
-- never retrieved — would put fabricated evidence into the ledger that change
-- detection reads, and `normalized_sha256` is exactly the value a policy-change
-- event keys on. A made-up hash there does not degrade gracefully: it either
-- suppresses a real change or announces a fake one.
--
-- WHY A TRIGGER RATHER THAN A LIST OF INSERTS
--
-- Sources are not all registered by the time this file runs. 72 later
-- migrations register more (20260821200000_register_ca_missing_sources.sql
-- onward, through Singapore and Finland), and each is followed by requirement
-- migrations that bind to what it just registered. A one-shot insert here
-- covers only the sources that exist at this point in the chain — which is how
-- the first attempt at this fix failed, at 20260821210001.
--
-- So the fixtures live in a table and a trigger plants one whenever a source is
-- registered. The alternative was appending a planting block to all 72
-- registration migrations, which edits files that are already applied in
-- production to solve a problem that only exists on an empty database.
--
-- The table, the function and the trigger are all dropped again by
-- 20260903130000_drop_source_version_fixtures.sql, once the last requirement
-- migration has run. Production therefore ends with none of this installed, and
-- the sync job is never competing with a trigger for the
-- one-active-version-per-source index.
--
-- NO-OP ON ANY DATABASE THAT HAS SYNCED
--
-- Planting is guarded on the source having no version at all, so production
-- skips every row: the fixtures are for empty databases only.
--
-- Sources are matched by (source_url, visa_type_id) — the natural key behind
-- visa_sources_url_per_type_idx — not by uuids, which differ on every fresh
-- database.
--
-- GENERATED FILE. Regenerate the fixture rows with
-- scripts/visa-registry/export-source-versions.sh.

begin;

create table if not exists public.visa_source_version_fixtures (
  source_url          text not null,
  visa_type_visaai_id text,
  version_number      integer not null,
  raw_sha256          text not null,
  normalized_sha256   text not null,
  http_status         integer,
  content_type        text,
  byte_size           integer,
  published_at        date,
  effective_from      date,
  extractor_version   text not null,
  fetched_at          timestamptz not null
);

comment on table public.visa_source_version_fixtures is
  'Replay-only fixtures: real active source versions exported from production '
  'so an empty database can satisfy visa_requirements.source_version_id. '
  'Dropped by 20260903130000 at the end of the chain.';

-- Not user data, but it is reachable through PostgREST while it exists, so it
-- gets the same default-deny posture as everything else in public.
alter table public.visa_source_version_fixtures enable row level security;

create unique index if not exists visa_source_version_fixtures_key_idx
  on public.visa_source_version_fixtures
     (source_url, coalesce(visa_type_visaai_id, ''));

insert into public.visa_source_version_fixtures (
