-- Planting is idempotent on two counts: a source that already has any version
-- is left alone, and a source with no fixture is left alone. Both are normal.
create or replace function public.plant_source_version_fixture(p_source_id uuid)
returns boolean
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
declare
  v_rows integer := 0;
begin
  insert into public.visa_source_versions (
    source_id, version_number, raw_sha256, normalized_sha256,
    http_status, content_type, byte_size, published_at, effective_from,
    extractor_version, fetched_at, is_active)
  select s.id, f.version_number, f.raw_sha256, f.normalized_sha256,
         f.http_status, f.content_type, f.byte_size, f.published_at,
         f.effective_from, f.extractor_version, f.fetched_at, true
    from public.visa_sources s
    join public.visa_source_version_fixtures f
      on f.source_url = s.source_url
     and coalesce(f.visa_type_visaai_id, '')
       = coalesce((select t.visaai_id from public.visa_types t
                    where t.id = s.visa_type_id), '')
   where s.id = p_source_id
     -- Never a second version for a source that has one. This is what makes the
     -- whole file a no-op in production and safe to re-run anywhere.
     and not exists (select 1 from public.visa_source_versions v
                      where v.source_id = s.id);

  get diagnostics v_rows = row_count;
  return v_rows > 0;
end;
$$;

comment on function public.plant_source_version_fixture(uuid) is
  'Replay-only. Gives a freshly registered source its exported production '
  'version so requirement migrations can bind to it. Dropped by 20260903130000.';

create or replace function public.plant_source_version_fixture_tg()
returns trigger
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
begin
  perform public.plant_source_version_fixture(new.id);
  return null;
end;
$$;

-- AFTER INSERT, statement-free, one row at a time: the registration migrations
-- insert sources in multi-row VALUES lists and every one of them needs a
-- version before the requirement migration that follows it.
drop trigger if exists visa_sources_plant_fixture_tg on public.visa_sources;
create trigger visa_sources_plant_fixture_tg
  after insert on public.visa_sources
  for each row execute function public.plant_source_version_fixture_tg();

-- The sources registered before this point in the chain never fired the
-- trigger, so plant theirs now.
do $$
declare
  r          record;
  v_planted  integer := 0;
begin
  for r in select id from public.visa_sources loop
    if public.plant_source_version_fixture(r.id) then
      v_planted := v_planted + 1;
    end if;
  end loop;

  raise notice 'source version fixtures: planted % of % already-registered sources',
    v_planted, (select count(*) from public.visa_sources);
end $$;

-- ---------------------------------------------------------------------------
-- Sources that were never fetched at all
-- ---------------------------------------------------------------------------
--
-- 79 of the 385 registered sources have no version anywhere, production
-- included, because their authority refuses the fetch: migri.fi and
-- immi.homeaffairs.gov.au answer the VPS with 403, robots.txt included. There
-- is nothing to export for them and nothing to invent.
--
-- Those sources still have requirement migrations written against them, and in
-- production those migrations FAILED — which is why 15 of 192 visa types (10
-- Australian, 5 Finnish) have zero requirements today. Nobody saw it, because
-- production applies migrations by piping files into psql and keeps no
-- schema_migrations ledger, so a file that rolled back left no trace.
--
-- On a replay the same inserts abort the whole chain. So for the duration of the
-- chain, a requirement whose source has no version is RECORDED AND SKIPPED
-- rather than fatal. The record is the point: an empty requirement list should
-- be visible as "we could not read this authority", not as "this route has no
-- requirements".
--
-- The skips table outlives the chain. The trigger does not — 20260903130000
-- drops it, so a null source_version_id in normal operation goes back to being
-- the not-null violation it should be.

create table if not exists public.visa_requirement_bootstrap_skips (
  visa_type_id     uuid not null references public.visa_types on delete cascade,
  requirement_code text not null,
  source_hint      text,
  recorded_at      timestamptz not null default now(),
  primary key (visa_type_id, requirement_code)
);

comment on table public.visa_requirement_bootstrap_skips is
  'Requirements a replay could not plant because their source has never been '
  'fetched successfully (authority blocks our egress). Empty in production, '
  'where those migrations failed outright instead. Read it to see which routes '
  'are silent because of a fetch failure rather than because they have no rules.';

alter table public.visa_requirement_bootstrap_skips enable row level security;

create or replace function public.record_unbindable_requirement()
returns trigger
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
begin
  if new.source_version_id is not null then
    return new;
  end if;

  insert into public.visa_requirement_bootstrap_skips (
    visa_type_id, requirement_code, source_hint)
  values (
    new.visa_type_id, new.requirement_code,
    'no fetched version for this requirement''s source')
  on conflict (visa_type_id, requirement_code) do nothing;

  -- Skip the row. NOT a substitute for the requirement: the route stays empty
  -- and the skips table says why.
  return null;
end;
$$;

drop trigger if exists visa_requirements_skip_unbindable_tg on public.visa_requirements;
create trigger visa_requirements_skip_unbindable_tg
  before insert on public.visa_requirements
  for each row execute function public.record_unbindable_requirement();

commit;
